/* PostgreSQL starting databases for the Supabase-style course. Every case starts from a fresh public schema.
   Supabase conventions are reproduced: roles anon, authenticated and service_role (which bypasses row-level
   security), auth.uid() read from the request claims, and default privileges that open every new public table
   to the API roles, so that row-level security is what actually protects the data. */
export const USERS={afi:'11111111-1111-1111-1111-111111111111',yao:'22222222-2222-2222-2222-222222222222',ama:'33333333-3333-3333-3333-333333333333',kofi:'44444444-4444-4444-4444-444444444444'};

/* Once per engine: cluster-wide roles. */
export const BOOTSTRAP=`do $$ begin
 if not exists (select from pg_roles where rolname='anon') then create role anon nologin; end if;
 if not exists (select from pg_roles where rolname='authenticated') then create role authenticated nologin; end if;
 if not exists (select from pg_roles where rolname='service_role') then create role service_role nologin bypassrls; end if;
end $$;`;

/* Before every case: an empty public schema, the auth helpers and Supabase-like default privileges. */
export const RESET=`reset role;
select set_config('request.jwt.claim.sub', '', false);
drop schema if exists public cascade;
drop schema if exists auth cascade;
create schema public;
create schema auth;
create function auth.uid() returns uuid language sql stable as $$ select nullif(current_setting('request.jwt.claim.sub', true), '')::uuid $$;
grant usage on schema public, auth to anon, authenticated, service_role;
grant execute on function auth.uid() to anon, authenticated, service_role;
alter default privileges in schema public grant all on tables to anon, authenticated, service_role;
alter default privileges in schema public grant all on sequences to anon, authenticated, service_role;
alter default privileges in schema public grant execute on functions to anon, authenticated, service_role;`;

const shop={
 profils:"create table profils (\n  id uuid primary key,\n  nom text not null,\n  role text not null default 'client' check (role in ('client', 'vendeur'))\n);",
 produits:"create table produits (\n  id bigint generated by default as identity primary key,\n  nom text not null,\n  prix integer not null check (prix > 0),\n  stock integer not null default 0 check (stock >= 0),\n  vendeur_id uuid references profils (id)\n);",
 commandes:"create table commandes (\n  id bigint generated by default as identity primary key,\n  client_id uuid not null references profils (id),\n  produit_id bigint not null references produits (id),\n  quantite integer not null check (quantite > 0),\n  statut text not null default 'en_attente' check (statut in ('en_attente', 'payee', 'livree'))\n);"
};
const shopColumns={profils:['id','nom','role'],produits:['id','nom','prix','stock','vendeur_id'],commandes:['id','client_id','produit_id','quantite','statut']};
const {afi,yao,ama,kofi}=USERS;
const datasets={
 'pg-boutique':{profils:[[afi,'Afi','client'],[yao,'Yao','client'],[ama,'Ama','vendeur'],[kofi,'Kofi','vendeur']],
  produits:[[1,'Riz parfumé',600,40,ama],[2,'Huile de palme',1500,12,ama],[3,'Gari',400,0,kofi],[4,'Savon noir',350,25,kofi]],
  commandes:[[1,afi,1,2,'payee'],[2,yao,2,1,'en_attente'],[3,afi,4,3,'livree']]},
 'pg-boutique-variation':{profils:[[afi,'Afi','client'],[yao,'Yao','client'],[ama,'Ama','vendeur'],[kofi,'Kofi','vendeur']],
  produits:[[1,'Maïs',300,100,kofi],[2,'Haricots',700,0,ama],[3,'Tomates',250,60,ama],[4,'Igname',900,8,kofi],[5,'Sel',150,30,ama]],
  commandes:[[1,yao,1,5,'payee'],[2,yao,3,2,'livree'],[3,afi,5,1,'en_attente'],[4,yao,4,1,'en_attente']]},
 'pg-vierge':null
};
export const pgFixtureIds=Object.keys(datasets);

export function pgPreview(id){
 if(!(id in datasets))throw Error('Base initiale inconnue.');
 const data=datasets[id];if(!data)return [];
 return Object.keys(shop).map(name=>({name,definition:shop[name],columns:shopColumns[name],values:data[name]||[]}));
}

const literal=v=>v===null?'null':typeof v==='number'?String(v):"'"+String(v).replaceAll("'","''")+"'";
/* SQL that builds the fixture, then moves identity sequences past the inserted ids. */
export function fixtureSql(id){
 const tables=pgPreview(id);
 return tables.map(t=>t.definition+(t.values.length?'\ninsert into '+t.name+' ('+t.columns.join(', ')+') values\n'+t.values.map(r=>'  ('+r.map(literal).join(', ')+')').join(',\n')+';':'')
  +(t.columns[0]==='id'&&t.definition.includes('identity')?`\nselect setval(pg_get_serial_sequence('${t.name}', 'id'), coalesce((select max(id) from ${t.name}), 0) + 1, false);`:'')).join('\n');
}
